parameters.text:
=You are an interview coach. Prepare this candidate for a {{ $('Interview details form').first().json.interview_type }} interview.

Job title: {{ $('Interview details form').first().json.job_title }}
Company: {{ $('Interview details form').first().json.company }}
Job description:
{{ $('Interview details form').first().json.job_description.slice(0, 8000) }}

Candidate CV:
{{ ($json.text || 'No CV text could be read.').replace(/\s+/g, ' ').slice(0, 10000) }}

Rules:
- Address the candidate as "you". Never assume or mention the candidate's gender, age or other personal traits.
- role_summary: one or two sentences on what the role needs and how your background fits.
- likely_questions: 10 questions mixing role-specific, behavioural and motivation questions for a {{ $('Interview details form').first().json.interview_type }} interview.
- answer_outline: a STAR outline (Situation, Task, Action, Result) built only from the CV. If the CV has no fitting example, say what kind of example to prepare instead. Never invent employers, numbers or projects.
- skills_to_highlight: 5 items. gaps_and_how_to_address: up to 4. questions_to_ask_them: 5 smart questions about the team, success measures and challenges.

parameters.jsonSchemaExample:
{
  "role_summary": "Mid-level data analyst owning weekly reporting for the sales team.",
  "likely_questions": [
    {
      "question": "Tell me about a dashboard that changed a decision.",
      "why_they_ask": "The role owns sales reporting.",
      "answer_outline": "Situation: ... Task: ... Action: ... Result: ..."
    }
  ],
  "skills_to_highlight": [
    "SQL",
    "Stakeholder communication"
  ],
  "gaps_and_how_to_address": [
    {
      "gap": "No Looker experience",
      "how_to_address": "Mention Power BI and a Looker course"
    }
  ],
  "questions_to_ask_them": [
    "How is success measured in the first 90 days?"
  ]
}

parameters.jsCode:
// Render the prep pack as HTML for the form's result page
const e = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const o = $json.output; const f = $('Interview details form').first().json;
const li = a => (a || []).map(x => `<li>${e(x)}</li>`).join('');
const qs = (o.likely_questions || []).map((q, i) => `<p><b>${i + 1}. ${e(q.question)}</b><br><i>Why they ask:</i> ${e(q.why_they_ask)}<br>${e(q.answer_outline).replace(/\n/g, '<br>')}</p>`).join('');
const gaps = (o.gaps_and_how_to_address || []).map(g => `<li><b>${e(g.gap)}</b>: ${e(g.how_to_address)}</li>`).join('');
const html = `<h3>${e(f.job_title)} at ${e(f.company)}</h3><p>${e(o.role_summary)}</p><h4>Likely questions</h4>${qs}` +
  `<h4>Skills to highlight</h4><ul>${li(o.skills_to_highlight)}</ul><h4>Gaps and how to handle them</h4><ul>${gaps}</ul>` +
  `<h4>Questions to ask them</h4><ul>${li(o.questions_to_ask_them)}</ul>`;
return [{ json: { html } }];
